// Pure-JS RSS / Atom parser (no deps, n8n Code-node restriction).
const src = $input.first().json;
const body = src.body || src.data || '';
const sourceMeta = $('Loop Over Sources').first().json;
if (!body || typeof body !== 'string') return [];
function stripCdata(s){return String(s||'').replace(/<!\[CDATA\[(.*?)\]\]>/gs,'$1').replace(/<[^>]+>/g,'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&nbsp;/g,' ').replace(/\s+/g,' ').trim();}
function extractTag(b,t){const re=new RegExp(`<${t}[^>]*>([\s\S]*?)<\/${t}>`,'i');const m=b.match(re);return m?stripCdata(m[1]):'';}
function extractAttr(b,t,a){const re=new RegExp(`<${t}[^>]*${a}="([^"]+)"`,'i');const m=b.match(re);return m?m[1]:'';}
const blocks = body.match(/<(item|entry)[\s\S]*?<\/(item|entry)>/gi) || [];
const cutoff = Date.now() - 14*24*60*60*1000;
const out=[];
for (const block of blocks.slice(0,25)){
  const title = extractTag(block,'title');
  if (!title) continue;
  let link = extractTag(block,'link') || extractAttr(block,'link','href');
  link = (link||'').trim();
  const description = extractTag(block,'description') || extractTag(block,'summary') || extractTag(block,'content');
  const pubRaw = extractTag(block,'pubDate') || extractTag(block,'updated') || extractTag(block,'published') || extractTag(block,'dc:date');
  const observed = pubRaw ? new Date(pubRaw) : new Date();
  if (Number.isNaN(observed.getTime())) continue;
  if (observed.getTime() < cutoff) continue;
  out.push({json:{sourceMeta, article:{title, link, description, observedAt: observed.toISOString()}}});
}
return out;

// Classify + score; same taxonomy as the radar's signalClassifier.
const SIGNAL_RULES = [
  { type:'insolvency',         re: /insolven[zc]|bankruptcy|chapter\s*11|pleite|insolvenzverfahren/i,                impact:-38, conf:0.92 },
  { type:'restructuring',      re: /restructur|reorgan|umstrukturier|stellenabbau|lay-?offs?|entlassung|streich.*stell|sparmaßnahm|werks?schließung/i, impact:-22, conf:0.78 },
  { type:'mna_buy',            re: /acquir(es|ed|ition)|\b(buys|kauft|übernimm|übernehm|übernomm|übernahme|erwirb|erwerb|erworb|fusion|takeover)/i, impact: 24, conf:0.82 },
  { type:'mna_sell',           re: /divest|sells .* (unit|division|business)|verkauft.*sparte|abspaltung|spin-?off/i,    impact:-14, conf:0.78 },
  { type:'gf_change',          re: /\bnew (ceo|cto|cfo|coo|chief)|appoint(s|ed)|ernennt|führungswechsel|rücktritt|abberufung/i, impact: 10, conf:0.74 },
  { type:'patent_filing',      re: /patent (filing|application|granted)|patentanmeldung/i,                              impact: 16, conf:0.78 },
  { type:'funding_grant',      re: /raised|series\s*[a-e]|funding round|förderung|grant|finanzierungsrunde|kapitalerhöh/i, impact: 22, conf:0.86 },
  { type:'location_expansion', re: /opens? .*office|new office|niederlassung|expand|standort|werk eröffn/i,             impact: 20, conf:0.80 },
  { type:'job_spike',          re: /hiring spree|job(s)? (spike|boom)|stellenanzeigen|ramp.*hiring|sucht \d{2,} (mitarbeit|fachkr)/i, impact: 26, conf:0.78 },
  { type:'employee_growth',    re: /headcount|workforce growth|mitarbeiter ?wachstum|baut \d{2,} stellen/i,             impact: 20, conf:0.74 },
  { type:'product_launch',     re: /launch(es|ed)|unveil(s|ed)|stellt vor|markteinführung/i,                            impact: 14, conf:0.72 },
  { type:'new_business_unit',  re: /new (division|business unit|geschäftsbereich)|spin-?off/i,                          impact: 18, conf:0.78 },
];
const items=[];
for (const it of $input.all()){
  const sourceMeta = it.json.sourceMeta||{};
  const article = it.json.article||{};
  const haystack = `${article.title||''} ${article.description||''}`;
  let pick=null;
  for (const r of SIGNAL_RULES){ if (r.re.test(haystack)){ pick=r; break; } }
  if (!pick){
    if (String(sourceMeta.source_type||'').toLowerCase().includes('press')) pick={type:'press_release', impact:6, conf:0.55};
    else continue;
  }
  const priority = Number(sourceMeta.priority||3);
  const trust = Math.max(0.6, Math.min(1, 1 - (priority-1)*0.08));
  const ageDays = Math.max(0, (Date.now()-new Date(article.observedAt).getTime())/86400000);
  const recencyBoost = ageDays<=1?1.1:ageDays<=7?1.0:0.9;
  const impact = Math.round(Math.max(-100, Math.min(100, pick.impact * recencyBoost)));
  const confidence = Math.max(0, Math.min(1, +(pick.conf * trust).toFixed(2)));
  items.push({ json: {
    companyName: sourceMeta.company_name,
    signalType: pick.type,
    source: sourceMeta.source_type || 'rss',
    title: article.title,
    description: (article.description||'').slice(0,500),
    impact, confidence,
    observedAt: article.observedAt,
    metadata: {
      url: article.link,
      region: sourceMeta.region||'',
      industry: sourceMeta.industry||'',
      country: sourceMeta.country||'',
      company_domain: sourceMeta.company_domain||'',
      workflow: 'rsg-hiring-signals-live-v2'
    }
  }});
}
return items;

// In-run dedup — same (company, signalType, observedAt, title-prefix) collapses.
const seen=new Set();
const out=[];
for (const it of $input.all()){
  const k = `${it.json.companyName}|${it.json.signalType}|${it.json.observedAt}|${(it.json.title||'').slice(0,80)}`;
  if (seen.has(k)) continue;
  seen.add(k);
  out.push(it);
}
return out;

// Build IngestLog row per article — now also captures the Hermes
// classification (intent / urgency / riskFlag) when available.
const rows=[];
for (const it of $input.all()){
  const payload = it.json.body ? it.json.body : {};
  const reqJson = $('Code · De-duplicate').all()[$itemIndex]?.json || {};
  const status = it.json.statusCode ?? it.json.status ?? null;
  const ok = status && status>=200 && status<300;
  const hermesResp = $('HTTP · Hermes /analyze-signal').all()[$itemIndex]?.json?.body || {};
  const a = hermesResp.analysis || {};
  rows.push({json: {
    run_at: new Date().toISOString(),
    company_name: reqJson.companyName||'',
    signal_type: reqJson.signalType||'',
    title: reqJson.title||'',
    url: (reqJson.metadata && reqJson.metadata.url)||'',
    impact: reqJson.impact ?? '',
    confidence: reqJson.confidence ?? '',
    status: ok ? 'ok' : 'error',
    response_code: status ?? '',
    error: ok ? '' : JSON.stringify(payload).slice(0,300),
    hermes_intent: a.intent || '',
    hermes_urgency: a.urgency || '',
    hermes_risk_flag: a.riskFlag === true ? 'true' : a.riskFlag === false ? 'false' : '',
    hermes_summary: (a.summary || '').slice(0, 240),
  }});
}
return rows;

// Compose a Telegram-friendly Markdown digest from the snapshot.
const snap = ($input.first().json && ($input.first().json.body || $input.first().json)) || {};
const hr = snap.market || {};
const macro = snap.macro || {};
const regions = snap.regions || {};
const tops = snap.opportunities || [];
const news = snap.breakingNews || [];
const when = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'short', timeStyle: 'short' });
const lines = [];
lines.push(`*RSG Hiring Signals · Daily Intelligence*`);
lines.push(`_${when} CET_`);
lines.push('');
lines.push(`📊 *Markt:* ${hr.totalSignals||0} Signale · Avg ${hr.averageHiringScore ?? '?'}/100 · ${hr.newSignals24h||0} neue 24h`);
const une = macro.deUnemployment || {};
const inf = macro.deInflation || {};
const ecb = macro.ecbRate || {};
const cli = macro.deCompositeLeadingIndicator || {};
lines.push(`🇩🇪 *Makro:* Arbeitslos ${une.rate ?? '–'}% · HICP ${inf.rate ?? '–'}% · ECB ${ecb.rate ?? '–'}% · CLI ${cli.value ?? '–'} (${cli.trend || '?'})`);
if (regions.quadrants && regions.quadrants.length){
  const q = regions.quadrants.slice(0,4).map((q)=>`${q.label} ${q.hiringRate.toFixed(0)}`).join(' · ');
  lines.push(`🗺 *Quadranten:* ${q}`);
}
if (tops && tops.length){
  lines.push('');
  lines.push('*Top Opportunities:*');
  for (const o of tops.slice(0,5)){
    lines.push(`• ${o.companyName} · ${o.industry} · ${o.opportunityScore}/100 · ${o.recommendedTiming}`);
  }
}
if (news && news.length){
  lines.push('');
  lines.push('*Wire feed (klassifiziert):*');
  for (const n of news.slice(0,4)){
    const tag = n.breaking ? '🔴' : '·';
    lines.push(`${tag} ${n.company} — ${n.signalType} (${n.source})`);
  }
}
return [{ json: { text: lines.join('\n') } }];
